async function compressImage(inputPath, outputPath, ratio) {
	const cwd = process.cwd();
	try {
		const metadata = await sharp(path.resolve(cwd, inputPath)).metadata();
		const newWidth = Math.round(metadata.width * ratio);
    // ...
